// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Health/info endpoint
	// (GET /_info)
	GetInfo(ctx context.Context, request GetInfoRequestObject) (GetInfoResponseObject, error)
	// Создать бронь на слот (только user). Опционально — запросить ссылку на конференцию.
	// (POST /bookings/create)
	PostBookingsCreate(ctx context.Context, request PostBookingsCreateRequestObject) (PostBookingsCreateResponseObject, error)
	// Список всех броней с пагинацией (только admin)
	// (GET /bookings/list)
	GetBookingsList(ctx context.Context, request GetBookingsListRequestObject) (GetBookingsListResponseObject, error)
	// Список броней текущего пользователя (только user)
	// (GET /bookings/my)
	GetBookingsMy(ctx context.Context, request GetBookingsMyRequestObject) (GetBookingsMyResponseObject, error)
	// Отменить бронь (только своя бронь, только user)
	// (POST /bookings/{bookingId}/cancel)
	PostBookingsBookingIdCancel(ctx context.Context, request PostBookingsBookingIdCancelRequestObject) (PostBookingsBookingIdCancelResponseObject, error)
	// Получить тестовый JWT по роли (ОБЯЗАТЕЛЬНО). Доступен без авторизации.
	// (POST /dummyLogin)
	PostDummyLogin(ctx context.Context, request PostDummyLoginRequestObject) (PostDummyLoginResponseObject, error)
	// Авторизация по email и паролю (ДОПОЛНИТЕЛЬНОЕ ЗАДАНИЕ — необязательно)
	// (POST /login)
	PostLogin(ctx context.Context, request PostLoginRequestObject) (PostLoginResponseObject, error)
	// Регистрация пользователя (ДОПОЛНИТЕЛЬНОЕ ЗАДАНИЕ — необязательно)
	// (POST /register)
	PostRegister(ctx context.Context, request PostRegisterRequestObject) (PostRegisterResponseObject, error)
	// Создать переговорку (только admin)
	// (POST /rooms/create)
	PostRoomsCreate(ctx context.Context, request PostRoomsCreateRequestObject) (PostRoomsCreateResponseObject, error)
	// Список переговорок (admin и user)
	// (GET /rooms/list)
	GetRoomsList(ctx context.Context, request GetRoomsListRequestObject) (GetRoomsListResponseObject, error)
	// Создать расписание переговорки (только admin, только один раз). Длительность слота 30 мин. После создания расписание изменить нельзя.
	// (POST /rooms/{roomId}/schedule/create)
	PostRoomsRoomIdScheduleCreate(ctx context.Context, request PostRoomsRoomIdScheduleCreateRequestObject) (PostRoomsRoomIdScheduleCreateResponseObject, error)
	// Список доступных для бронирования слотов по переговорке и дате (admin и user). Наиболее нагруженный эндпоинт.
	// (GET /rooms/{roomId}/slots/list)
	GetRoomsRoomIdSlotsList(ctx context.Context, request GetRoomsRoomIdSlotsListRequestObject) (GetRoomsRoomIdSlotsListResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

